// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(242000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: string[] = [];
    page.on('pageerror', (err) => errors.push(err.message));

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    // Wait for network activities to finish
    await page.waitForTimeout(5000);

    await page.evaluate(() => {
  const container = document.querySelector('.zoom-container');
  const img = container ? container.querySelector('.zoom-image') : null;
  const overlay = container ? container.querySelector('.zoom-overlay') : null;
  return {
    hasZoomContainer: !!container,
    hasZoomImage: !!img,
    hasZoomOverlay: !!overlay,
    overlayActive: overlay ? overlay.classList.contains('zoom-overlay--active') : false,
    imgSrc: img ? img.src : null
  };
});

    await expect(page.getByRole('heading', { name: 'Sunglasses' })).toBeVisible();
    await expect(page.locator('.zoom-container')).toBeVisible();
    await expect(page.locator('.zoom-image')).toBeVisible();
    await expect(page.locator('.zoom-image')).toHaveAttribute('src', /sunglasses/);
    await expect(page.locator('.zoom-overlay')).toBeAttached();
    await expect(page.locator('.zoom-overlay')).not.toHaveClass(/zoom-overlay--active/);

    await page.locator('.zoom-container').dispatchEvent('mouseenter');
    await expect(page.locator('.zoom-overlay')).toHaveClass(/zoom-overlay--active/);
    await page.locator('.zoom-container').dispatchEvent('mouseleave');
    await expect(page.locator('.zoom-overlay')).not.toHaveClass(/zoom-overlay--active/);

    expect(errors).toHaveLength(0);
});
